from __future__ import annotations

import tarfile
import zlib
from pathlib import Path
from typing import Callable, Optional, Sequence, TypeVar, Union

import structlog

from rasa.exceptions import ValidationError

ModelPathArg = Union[str, Path, Sequence[Union[str, Path, None]], None]

ENGINE_VERSION_KEY = "engine_version"
CALM_ENGINE_VERSION = "calm"
MANTLE_ENGINE_VERSION = "mantle"
DEFAULT_ENGINE_VERSION = CALM_ENGINE_VERSION
VALID_ENGINE_VERSIONS = (
    CALM_ENGINE_VERSION,
    MANTLE_ENGINE_VERSION,
)
# Written to model metadata by Rasa 3.20.x; those models must still load.
LEGACY_CALM_ENGINE_VERSION = "calm_v1"

T = TypeVar("T")

structlogger = structlog.get_logger()


def resolve_runtime_engine_version(metadata_engine_version: str) -> str:
    """Resolve engine version for runtime CLI from packaged model metadata.

    Train/validate use :func:`resolve_engine_version` (project layout on disk).
    Run, inspect, shell, and other model-loading paths use the value stored in
    ``metadata.json`` inside the model archive. The legacy ``calm_v1`` value
    stored by Rasa 3.20.x models resolves to ``calm``.
    """
    if metadata_engine_version == LEGACY_CALM_ENGINE_VERSION:
        return CALM_ENGINE_VERSION
    if metadata_engine_version in VALID_ENGINE_VERSIONS:
        return metadata_engine_version

    raise ValidationError(
        code="config.engine_version.invalid_metadata",
        engine_version=metadata_engine_version,
        valid_engine_versions=VALID_ENGINE_VERSIONS,
        event_info=(
            f"Model metadata '{ENGINE_VERSION_KEY}' must be one of "
            f"{VALID_ENGINE_VERSIONS}, but found '{metadata_engine_version}'."
        ),
    )


def resolve_engine_version(
    *,
    config_path: Path | str | None = None,
) -> str:
    """Resolve engine version from on-disk project layout.

    Derives the root from *config_path*'s parent directory.
    Otherwise, returns :data:`DEFAULT_ENGINE_VERSION`.
    """
    from rasa.shared.project_structure import resolve_engine_version_from_project

    if config_path is None:
        return DEFAULT_ENGINE_VERSION

    return resolve_engine_version_from_project(Path(config_path).resolve().parent)


def _first_model_path(
    model_path: ModelPathArg,
) -> Optional[Union[str, Path]]:
    """Return a single path from a CLI ``--model`` value.

    ``rasa test core`` passes ``nargs="+"``, so ``model`` is a list (and may
    contain ``None`` when no archive exists yet). Other commands pass a string
    or omit the flag. Callers only need one readable archive for layout checks.
    """
    if model_path is None or isinstance(model_path, (str, Path)):
        return model_path
    for candidate in model_path:
        if candidate is not None:
            return candidate
    return None


def resolve_engine_version_for_cli(
    *,
    project_root: Union[str, Path, None] = None,
    model_path: ModelPathArg = None,
) -> str:
    """Resolve the engine version for CLI startup.

    A readable model whose ``engine_version`` matches the on-disk layout
    returns that version. When they disagree, the layout wins and a warning
    records it, except for one serve shape: a Mantle archive plus
    ``integrations.yml`` in a directory that is not a CALM project
    (no ``domain.yml``) and not a two-of-three Mantle layout. Skills for that
    deploy live in the archive, so the archive supplies the engine and the
    disagreement warning is not logged.

    A missing ``engine_version``, or an archive that cannot be read, does not
    count as Mantle. In that serve shape the layout stays ``calm`` and a
    warning says ``integrations.yml`` was not used. An explicit ``calm``
    archive agrees with the layout, so that warning is not logged.

    A Mantle project directory that still contains a ``calm`` archive keeps
    the layout. Tracing and metrics then come from ``integrations.yml``, while
    the model itself still runs on the engine in its metadata (see
    :func:`resolve_runtime_engine_version`), so the stale archive should be
    retrained.
    """
    from rasa.shared.project_structure import resolve_engine_version_from_project

    root = Path(project_root) if project_root is not None else Path.cwd()
    layout_version = resolve_engine_version_from_project(root)

    single_model_path = _first_model_path(model_path)
    if single_model_path is not None:
        metadata_version = _try_read_engine_version_from_model(single_model_path)
        if metadata_version is None:
            _warn_if_integrations_yml_skipped(root, layout_version, single_model_path)
        elif metadata_version == layout_version:
            return metadata_version
        elif _mantle_archive_supplies_engine(root, layout_version, metadata_version):
            return metadata_version
        else:
            structlogger.warning(
                "engine_version.archive_disagrees_with_layout",
                archive_engine_version=metadata_version,
                layout_engine_version=layout_version,
                event_info=(
                    f"The model archive was built with engine version "
                    f"'{metadata_version}', but the project layout uses "
                    f"'{layout_version}'. Using '{layout_version}'; retrain the "
                    f"model to match the project."
                ),
            )

    return layout_version


def _integrations_yml_selects_archive_engine(
    project_root: Path,
    layout_version: str,
) -> bool:
    """Return whether a Mantle archive may define the engine here.

    True when ``integrations.yml`` is present, ``domain.yml`` is not, and the
    layout is the default ``calm`` left by incomplete Mantle markers. A
    CALM project and a two-of-three Mantle layout are excluded.
    """
    from rasa.shared.project_structure import CALM_DOMAIN_FILE, MANTLE_INTEGRATIONS_FILE

    if layout_version != CALM_ENGINE_VERSION:
        return False
    if (project_root / CALM_DOMAIN_FILE).is_file():
        return False
    return (project_root / MANTLE_INTEGRATIONS_FILE).is_file()


def _warn_if_integrations_yml_skipped(
    project_root: Path,
    layout_version: str,
    model_path: Union[str, Path],
) -> None:
    """Warn when this serve shape leaves ``integrations.yml`` unused.

    Logged above DEBUG so a truncated archive, or one with no
    ``engine_version``, does not drop Mantle channels without a signal.
    """
    from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE

    if not _integrations_yml_selects_archive_engine(project_root, layout_version):
        return
    structlogger.warning(
        "engine_version.integrations_yml_skipped",
        event_info=(
            f"'{MANTLE_INTEGRATIONS_FILE}' was not used because the model at "
            f"'{model_path}' has no readable Mantle engine version. Channels "
            "stay on credentials.yml. Tracker store, lock store, event broker, "
            "timer store, model server, and the secrets manager stay on "
            "endpoints.yml."
        ),
    )


def _mantle_archive_supplies_engine(
    project_root: Path,
    layout_version: str,
    metadata_version: str,
) -> bool:
    """Return whether a Mantle archive defines the engine for this directory.

    True only when the archive is Mantle and
    :func:`_integrations_yml_selects_archive_engine` is true. The default
    ``calm`` layout in that case means the markers were incomplete, not that
    the project was identified as CALM.
    """
    if metadata_version != MANTLE_ENGINE_VERSION:
        return False
    return _integrations_yml_selects_archive_engine(project_root, layout_version)


def is_mantle_cli_context(
    *,
    project_root: Union[str, Path, None] = None,
    model_path: ModelPathArg = None,
) -> bool:
    """Return whether the CLI context should use Mantle integrations behaviour."""
    return (
        resolve_engine_version_for_cli(project_root=project_root, model_path=model_path)
        == MANTLE_ENGINE_VERSION
    )


def _try_read_engine_version_from_model(
    model_path: Union[str, Path],
) -> Optional[str]:
    """Return packaged ``engine_version`` when a model archive can be read.

    Reads only ``metadata.json`` from the archive, so CLI startup does not
    extract the whole model just to pick an engine.

    Returns ``None`` when the path is missing, empty, or not a valid archive,
    and when ``metadata.json`` has no ``engine_version`` key. Callers then fall
    back to project layout without aborting the command. A missing key is not
    treated as ``calm``: that default would hide the skip of
    ``integrations.yml`` on the archive-only serve shape.
    """
    # Lazy imports: this module is imported early; keep the model stack optional.
    from rasa.engine.storage.local_model_storage import LocalModelStorage
    from rasa.model import get_latest_model

    path = Path(model_path)
    try:
        archive_path: Optional[str]
        if path.is_file():
            archive_path = str(path)
        elif path.is_dir():
            archive_path = get_latest_model(str(path))
        else:
            return None
        if archive_path is None:
            return None
        serialized = LocalModelStorage.serialized_metadata_from_archive(archive_path)
        if not isinstance(serialized, dict):
            return None
        if ENGINE_VERSION_KEY not in serialized:
            structlogger.debug(
                "engine_version.model_metadata_missing_key",
                model_path=str(model_path),
                event_info=(
                    f"Model at '{model_path}' has no '{ENGINE_VERSION_KEY}' "
                    "in metadata.json; falling back to project layout."
                ),
            )
            return None
        return resolve_runtime_engine_version(serialized[ENGINE_VERSION_KEY])
    except (
        ValidationError,
        # Truncated or corrupt gzip stream.
        tarfile.TarError,
        EOFError,
        zlib.error,
        OSError,
        # Malformed metadata.json.
        ValueError,
        RecursionError,
    ) as error:
        structlogger.debug(
            "engine_version.model_metadata_unreadable",
            model_path=str(model_path),
            error_type=type(error).__name__,
            event_info=(
                f"Could not read engine version from model at '{model_path}'; "
                "falling back to project layout."
            ),
        )
        return None


def dispatch_by_engine_version(
    engine_version: str,
    calm_v1_handler: Callable[[], T],
    mantle_handler: Callable[[], T],
) -> T:
    """Dispatches execution based on the resolved engine version."""
    if engine_version == CALM_ENGINE_VERSION:
        return calm_v1_handler()
    if engine_version == MANTLE_ENGINE_VERSION:
        return mantle_handler()

    raise ValidationError(
        code="config.engine_version.unsupported_value",
        engine_version=engine_version,
        valid_engine_versions=VALID_ENGINE_VERSIONS,
        event_info=(
            f"Unsupported '{ENGINE_VERSION_KEY}' value '{engine_version}'. "
            f"Expected one of {VALID_ENGINE_VERSIONS}."
        ),
    )
